function spreadLabel(spread){return state.lang==="he"?spread.he:(UI_LOCALES[state.lang]?.[spread.en]??spread.en);}
function spreadPositions(spread){return state.lang==="he"?spread.pos_he:spread.pos_en.map(t=>UI_LOCALES[state.lang]?.[t]??t);}

